if(/^remove that foul/.test(n)){const e=[...effectiveEvents(state)].reverse().find(e=>e.type==='STAT'&&e.stat==='pf');if(!e)throw Error('No foul to remove.');return {events:[ev('PATCH',{patches:[{id:e.id,values:{removed:true}}]})],label:'Last foul removed'};}
if(/^change that 3 to (?:a )?2/.test(n)){const e=[...effectiveEvents(state)].reverse().find(e=>e.type==='SHOT'&&e.value===3);if(!e)throw Error('No three-point shot to correct.');return {events:[ev('PATCH',{patches:[{id:e.id,values:{value:2,points:e.made*2}}]})],label:'Three changed to two'};}
