if(/\b(in|out|entered|checks|checking)\b/.test(t)&&!/^set |^take \d/.test(t)){let parts=t.replace(/\bout\s+(?=(?:player |number )?(?:\d+|[a-z]+)\s+(?:checks )?in\b)/g,'out, ').split(/,|\band\b/).filter(x=>x.trim()),events=[];for(const part of parts){if(!/[a-z0-9]/.test(part))continue;const p=player(part),type=/\bout\b/.test(part)?'PLAYER_OUT':'PLAYER_IN';events.push(ev(type,{playerId:p.id,team:p.team}));}if(!events.length)throw Error('Specify the player entering or leaving.');return plan(events,events.map(e=>`#${d.players[e.playerId].number} ${e.type==='PLAYER_IN'?'in':'out'}`).join(' · '));}
