let stat=null;if(/offensive rebound|\bo board\b/.test(t))stat='oreb';else if(/defensive rebound|\bd board\b/.test(t))stat='dreb';else if(/\brebound\b|\bboard\b/.test(t))throw Error('Was that an offensive or defensive rebound?');else for(const [word,key] of [['assist','ast'],['steal','stl'],['block','blk'],['turnover','to'],['foul','pf']])if(new RegExp(`\\b${word}s?\\b`).test(t))stat=key;
