export function configPlan(settings,state){if(state.clock.started)throw Error('Game settings are locked after tip-off.');if(!settings.home.trim()||!settings.away.trim())throw Error('Enter both team names.');for(const [k,min,max] of [['periods',1,12],['length',60,3600],['overtime',60,1200],['foulLimit',1,10],['timeouts',0,20]])if(!Number.isInteger(settings[k])||settings[k]<min||settings[k]>max)throw Error(`Check ${k}; enter a whole number in the allowed range.`);return {events:[{type:'CONFIG',settings}],clock:{seconds:settings.length},label:'Game settings saved'};}
export function playerPlan(p,state){const {roster}=settingsAndRoster(state);p={id:uid(),number:'',first:'',last:'',nickname:'',aliases:[],team:'home',...p};p.number=String(p.number).trim();p.first=p.first.trim();p.last=(p.last||'').trim();if(!/^\d{1,3}$/.test(p.number)||!p.first||!['home','away'].includes(p.team))throw Error('Enter a jersey number (0–999), first name, and team.');if(roster.some(q=>q.number===p.number&&q.team===p.team))throw Error('That jersey number is already on this team.');return {events:[{type:'ADD_PLAYER',player:p}],label:`Added #${p.number} ${p.first}`};}
export function applyPlan(state,plan,raw=''){if(plan.undo)return undo(state);if(!plan.events?.length)throw Error('No event to record.');const d=derive(state),c=currentClock(state),cp=plan.clock||{},events=[...plan.events];if(cp.period>c.period&&c.started&&!events.some(e=>e.type==='QUARTER_START'||e.type==='PATCH')){const transitions=[];if(!c.break)transitions.push({type:'QUARTER_END',period:c.period,clock:0});for(let p=c.period+1;p<=cp.period;p++){transitions.push({type:'QUARTER_START',period:p,clock:lengthFor(p,d.settings)});if(p<cp.period)transitions.push({type:'QUARTER_END',period:p,clock:0});}events.unshift(...transitions);cp.break=false;}commit(state,events,raw,cp);return plan.label;}
export function describe(e,d){const p=d.players[e.playerId],who=p?`#${p.number} ${p.first} ${p.last}`:d.settings[e.team||'home'];if(e.type==='SHOT')return `${who} · ${e.value===1?`${e.made}/${e.attempts||1} free throws`:e.value+'PT '+(e.made?'made':'missed')}`;if(e.type==='STAT')return `${who} · ${e.stat.toUpperCase()}`;if(e.type==='PLAYER_IN'||e.type==='PLAYER_OUT')return `${who} · ${e.type==='PLAYER_IN'?'IN':'OUT'}`;if(e.type==='SCORE_CORRECTION')return `${who} · score correction ${e.absolute!==undefined?'to '+e.absolute:(e.delta>=0?'+':'')+e.delta}`;return `${e.type.replaceAll('_',' ')}${e.type.includes('TIMEOUT')?' · '+who:''}`;}
export function validateImport(obj){if(obj?.version!==1||!Array.isArray(obj.transactions)||obj.transactions.length>100000||!obj.clock)throw Error('This is not a supported Courtside game backup.');if(!Number.isInteger(obj.clock.period)||!Number.isFinite(obj.clock.seconds))throw Error('Invalid game clock in backup.');const allowed=new Set(['CONFIG','ROSTER','ADD_PLAYER','STARTERS','GAME_START','QUARTER_START','QUARTER_END','GAME_END','PLAYER_IN','PLAYER_OUT','STAT','SHOT','SCORE_CORRECTION','TEAM_TIMEOUT','TIMEOUT_RETURN','CLOCK_START','CLOCK_STOP','CLOCK_SYNC','SAME_FIVE','PATCH']);const ids=new Set();for(const t of obj.transactions){if(!t.id||ids.has(t.id)||!Array.isArray(t.events))throw Error('Invalid event ledger.');ids.add(t.id);for(const e of t.events){if(!allowed.has(e.type)||!Number.isInteger(e.period)||!Number.isFinite(e.clock)||e.clock<0)throw Error('Invalid event in backup.');if(e.type==='SHOT'&&(![1,2,3].includes(e.value)||!Number.isInteger(e.made)||e.made<0||!Number.isInteger(e.attempts)||e.attempts<1||e.made>e.attempts))throw Error('Invalid shot in backup.');if(e.type==='STAT'&&!statKeys.includes(e.stat))throw Error('Invalid stat in backup.');}}const d=derive(obj);if(d.roster.length>100||d.roster.some(p=>!p.id||!p.first||!['home','away'].includes(p.team)||!Array.isArray(p.aliases)))throw Error('Invalid roster in backup.');return obj;}
